"use client";

import dynamic from "next/dynamic";

// `late` is next/dynamic called through a helper on purpose: the build then adds no <link rel="preload"> for the chunk to the page HTML (a literal
// dynamic(() => import()) does), so the code of a section is downloaded when React really needs it (see lazy-hydrate.tsx), not at page load.
const late: typeof dynamic = (load) => dynamic(load, {});

// GENERATED by tools/lazy-codemod.mjs (re-run it after adding a big client component). Each line is its own chunk: a page downloads
// the code of the components it renders, not of all of them. They are still rendered on the server, so the HTML and SEO are the same.
